KW = sorted(((unicodedata.normalize('NFKC', k), r) for r, ks in R.items() for k in ks), key=lambda x: -len(x[0]))

def classify(text):
    score = {}
    t = text
    for k, r in KW:
        n = t.count(k)
        if n:
            score[r] = score.get(r, 0) + n * (len(k) ** 1.3)
            t = t.replace(k, '　' * len(k))  # consume to avoid sub-matches
    if not score: return 'gl'
    best = max(score.values())
    for r in PRIORITY:
        if score.get(r, 0) == best: return r
    return 'gl'

def z2h(s): return unicodedata.normalize('NFKC', s)

DATE_RES = [
    (re.compile(r'^(\d+)万年前$'), lambda m: (-int(m[1]) * 10000, 1, None, None)),
    (re.compile(r'^(\d+)～?(\d+)?万年前$'), lambda m: (-int(m[1]) * 10000, 1, None, None)),
    (re.compile(r'^(\d+)-(\d+)万年前$'), lambda m: (-int(m[1]) * 10000, 1, None, None)),
    (re.compile(r'^(\d+)年前$'), lambda m: (2000 - int(m[1]), 1, None, None)),
    (re.compile(r'^前(\d+)年紀$'), lambda m: (-int(m[1]) * 1000 + 500, 1, None, None)),
    (re.compile(r'^前(\d+)(?:-前(\d+))?世紀(.*)$'), lambda m: (-(int(m[1]) - 1) * 100 - 50, 1, None, None)),
    (re.compile(r'^(\d+)(?:-(\d+))?世紀(.*)$'), lambda m: ((int(m[1]) - 1) * 100 + 50, 1, None, None)),
    (re.compile(r'^(\d+)(?:-(\d+))?bc([*?]?)(?:\s+(\d+)(?:/(\d+))?)?$'), lambda m: (-int(m[1]), 1 if m[3] else 0, int(m[4]) if m[4] else None, int(m[5]) if m[5] else None)),
    (re.compile(r'^(\d+)(?:-(\d+))?([*?]?)(?:\s+(\d+)(?:/(\d+))?)?$'), lambda m: (int(m[1]), 1 if m[3] else 0, int(m[4]) if m[4] else None, int(m[5]) if m[5] else None)),
]

def parse_date(s):
    s = z2h(s).strip()
    s = s.replace('〜', '-').replace('～', '-')
    if s in ('〃', '"'): return 'same'
    for rx, fn in DATE_RES:
        m = rx.match(s)
        if m: return fn(m)
    return None

events = []
cur = None
lines = open(SRC, encoding='utf-8').read().splitlines()
for raw in lines[4:]:
    if '▲' in raw: continue
    st = raw.strip().strip('　')
    if not st: continue
    d = parse_date(st)
    if d == 'same': continue
    if d:
        cur = d
        continue
    if cur is None: continue
    text = z2h(st).strip()
    text = re.sub(r'\s+', ' ', text).replace('。。', '。')
    if text.startswith('-') and re.match(r'^-\d', text): continue
    y, c, mo, da = cur
    if mo and mo > 12: mo, da = None, None
    e = {'y': y if y != 0 else 1, 't': text, 'r': classify(text)}
    if c: e['c'] = 1
    if mo: e['m'] = mo
    if da: e['d'] = da
    events.append(e)

with open(OUT, 'w', encoding='utf-8') as f:
    f.write('CM.data.events(%s);\n' % json.dumps(events, ensure_ascii=False, separators=(',', ':')))
from collections import Counter
print(len(events), Counter(e['r'] for e in events))
